  f(7, 10, 16, 12, CLAY)
  if (pose.isCheering) f(3, 10, 4, 4, CLAY, 'ar')
  else f(3, 14, 4, 4, CLAY)
  f(23, 14 + (pose.isCheering && !armCls ? -4 : armFront), 4, 4, CLAY, armCls ?? (pose.isCheering ? 'ar' : undefined))
